//! Stabled's background theme gallery: images bundled with the launcher, grouped by category.
//! The manifest (`src/lib/backgrounds.json`) is generated by `tools/build_backgrounds.py` and shared with the UI;
//! the images are bundled as `backgrounds/<category>--<image>.jpg` resources.

use crate::bail;
use crate::error::AppResult;
use serde::Deserialize;
use std::path::PathBuf;
use std::sync::OnceLock;

const MANIFEST: &str = include_str!("../../src/lib/backgrounds.json");

#[derive(Deserialize)]
struct Manifest {
    categories: Vec<Category>,
}

#[derive(Deserialize)]
struct Category {
    id: String,
    images: Vec<ImageEntry>,
}

#[derive(Deserialize)]
struct ImageEntry {
    id: String,
}

static DIR: OnceLock<PathBuf> = OnceLock::new();

/// Set once at startup to the bundled `backgrounds` resource folder.
pub fn set_dir(dir: PathBuf) {
    let _ = DIR.set(dir);
}

/// The bundled gallery folder (images and `index.json`), passed to the game so its menus offer the same pre-themes.
pub fn dir() -> Option<&'static PathBuf> {
    DIR.get()
}

fn manifest() -> Manifest {
    serde_json::from_str(MANIFEST).unwrap_or(Manifest { categories: Vec::new() })
}

/// The bundled file for a gallery id ("<category>/<image>"), checked against the manifest so no other path
/// can be reached from the UI.
pub fn path_for(id: &str) -> AppResult<PathBuf> {
    let Some((cat, img)) = id.split_once('/') else { bail!("GALLERY", "Unknown background") };
    let known = manifest().categories.iter().any(|c| c.id == cat && c.images.iter().any(|i| i.id == img));
    if !known {
        bail!("GALLERY", "Unknown background");
    }
    let Some(dir) = DIR.get() else { bail!("GALLERY", "The background gallery isn't included in this build.") };
    let path = dir.join(format!("{cat}--{img}.jpg"));
    if !path.is_file() {
        bail!("GALLERY", "That background is missing from this installation. Reinstall Stabled to restore it.");
    }
    Ok(path)
}

#[cfg(test)]
mod tests {
    #[test]
    fn manifest_is_valid_and_ids_are_checked() {
        let m = super::manifest();
        assert!(!m.categories.is_empty(), "the gallery manifest should list categories");
        assert!(m.categories.iter().all(|c| !c.images.is_empty()));
        assert!(super::path_for("../../etc/passwd").is_err());
        assert!(super::path_for("not-a-category/01").is_err());
    }
}
